import{_ as t,o as a,c as s,a2 as o}from"./chunks/framework.CyZTVJbV.js";const m=JSON.parse('{"title":"Fidelity — dogfood-form-ct (v1.16-3)","description":"","frontmatter":{},"headers":[],"relativePath":"quality-reports/component/form-ct.md","filePath":"quality-reports/component/form-ct.md"}'),i={name:"quality-reports/component/form-ct.md"};function d(r,e,n,l,c,p){return a(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="fidelity-—-dogfood-form-ct-v1-16-3" tabindex="-1">Fidelity — dogfood-form-ct (v1.16-3) <a class="header-anchor" href="#fidelity-—-dogfood-form-ct-v1-16-3" aria-label="Permalink to &quot;Fidelity — dogfood-form-ct (v1.16-3)&quot;">​</a></h1><p>Real-vs-mock behavioural fidelity for the 5 form Playwright Component Testing dogfood, produced by <code>examples/dogfood-form-ct/tests/emit-fidelity-report.test.ts</code>. Feeds <code>@kiwa-test/quality-metrics</code> 7-axis release gate.</p><h2 id="baseline-real-mode-skipped-—-no-pw-ct-endpoint-and-no-live-playwright-experimental-ct-react-install" tabindex="-1">Baseline (real mode skipped — no <code>PW_CT_ENDPOINT</code> and no live <code>@playwright/experimental-ct-react</code> install) <a class="header-anchor" href="#baseline-real-mode-skipped-—-no-pw-ct-endpoint-and-no-live-playwright-experimental-ct-react-install" aria-label="Permalink to &quot;Baseline (real mode skipped — no \`PW_CT_ENDPOINT\` and no live \`@playwright/experimental-ct-react\` install)&quot;">​</a></h2><p>When the harness runs without a <code>PW_CT_ENDPOINT</code> env var, the real adapter emits <code>PW_CT_REAL_ENV_MISSING</code> for every op. Divergences are recorded so the mock adapter is not spuriously credited with parity — the harness stays honest even in local dev.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>provider   : @kiwa-test/component/form-ct</span></span>
<span class="line"><span>version    : 0.1.0</span></span>
<span class="line"><span>verdict    : PASS (7-axis component branch — all axes clear the default gate)</span></span>
<span class="line"><span>divergences: 4 (mount / interactValidation / interactSubmit / checkA11y — real mode absent)</span></span>
<span class="line"><span>axes       : 7 (component branch — no AI-LLM cost / latency / token / accuracy overlay)</span></span></code></pre></div><table tabindex="0"><thead><tr><th>axis</th><th>actual</th><th>threshold</th><th>verdict</th></tr></thead><tbody><tr><td>coverage.line</td><td>92.00%</td><td>85%</td><td>pass</td></tr><tr><td>coverage.branch</td><td>88.00%</td><td>80%</td><td>pass</td></tr><tr><td>coverage.function</td><td>95.00%</td><td>90%</td><td>pass</td></tr><tr><td>fidelity.ratio</td><td>100.00% (4/4)</td><td>70%</td><td>pass</td></tr><tr><td>perf.p95Ms</td><td>~0.60 ms</td><td>100 ms</td><td>pass</td></tr><tr><td>mutation.killRate</td><td>73.33% (22/30)</td><td>60%</td><td>pass</td></tr><tr><td>testCount.behavior</td><td>50</td><td>10</td><td>pass</td></tr></tbody></table><p>Fidelity ratio counts mock-covered ops vs the real Playwright CT surface (4 total — <code>mount</code> / <code>interactValidation</code> / <code>interactSubmit</code> / <code>checkA11y</code>). Divergences count all 4 because the real adapter is skipped when <code>PW_CT_ENDPOINT</code> is absent — that is by design, wiring the env promotes the report to the real baseline.</p><h2 id="reproduction" tabindex="-1">Reproduction <a class="header-anchor" href="#reproduction" aria-label="Permalink to &quot;Reproduction&quot;">​</a></h2><p>Mock only.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dogfood-form-ct</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/dogfood-form-ct/quality-report/fidelity-latest.md</span></span></code></pre></div><p>Live real mode.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PW_CT_ENDPOINT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">http://localhost:3100</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># optional — force a specific browser channel through the CT runner</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PW_CT_BROWSER</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">chromium</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dogfood-form-ct</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span></code></pre></div><p>The v0.1 real adapter emits <code>PW_CT_LIVE_NOT_IMPLEMENTED</code> when <code>PW_CT_ENDPOINT</code> is set — a follow-up milestone will swap in an <code>@playwright/experimental-ct-react</code> preview channel driver that exercises real browser mount + interact + a11y (axe-core) on every form kind.</p><h2 id="ops-under-measurement" tabindex="-1">Ops under measurement <a class="header-anchor" href="#ops-under-measurement" aria-label="Permalink to &quot;Ops under measurement&quot;">​</a></h2><p>Four provider-neutral ops on <code>FormCTAdapter</code>.</p><ul><li><code>mount</code> — renders 1 form kind into an in-memory MockNode canvas via <code>@kiwa-test/component</code> <code>createPlaywrightCTMock().mount(...)</code> and returns a summary (formId + kind + fieldCount + submitButtonLabel + hasFormElement)</li><li><code>interactValidation</code> — mounts the form, clicks the submit button with the validation-args fixture, captures the reported <code>FormValidationError</code> + the <code>role=alert</code> region&#39;s text, asserts <code>onSubmit</code> did not fire</li><li><code>interactSubmit</code> — mounts the form with the happy-path fixture, clicks submit, captures the <code>FormSubmitPayload</code>, asserts <code>onValidationError</code> did not fire</li><li><code>checkA11y</code> — mounts the form through <code>@kiwa-test/component</code> <code>createStoryRegistry</code> and runs the heuristic checker (button-name / image-alt / label rules) — every form is expected to pass</li></ul><h2 id="_5-form-patterns-ssot-for-saas-front-ends" tabindex="-1">5 form patterns (SSOT for SaaS front ends) <a class="header-anchor" href="#_5-form-patterns-ssot-for-saas-front-ends" aria-label="Permalink to &quot;5 form patterns (SSOT for SaaS front ends)&quot;">​</a></h2><p>The dogfood exercises the 5 form primitives that show up in every commercial SaaS onboarding / checkout / account flow. Each has 1 required field + at least 1 optional path, and every form is asserted on 4 axes — mount / validation / submit / a11y = 0.</p><table tabindex="0"><thead><tr><th>kind</th><th>fields</th><th>required</th><th>validation branch</th><th>submit payload keys</th></tr></thead><tbody><tr><td>login</td><td>email + password + rememberMe</td><td>email + password</td><td>missing password</td><td>email / password / rememberMe</td></tr><tr><td>signup</td><td>email + password + passwordConfirm + acceptedTerms</td><td>all 4 + password === confirm</td><td>password mismatch</td><td>email / password / passwordConfirm / acceptedTerms</td></tr><tr><td>checkout</td><td>fullName + address + city + postalCode + cardNumber</td><td>all 5 + card matches <code>\\d{12,19}</code></td><td>malformed cardNumber</td><td>fullName / address / city / postalCode / cardNumber</td></tr><tr><td>profile</td><td>displayName + bio + websiteUrl</td><td>displayName + URL well-formed when present</td><td>malformed URL</td><td>displayName / bio / websiteUrl</td></tr><tr><td>search</td><td>query + filterCategory</td><td>query</td><td>empty query</td><td>query / filterCategory</td></tr></tbody></table><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><p>Provider prefix <code>@kiwa-test/component/</code> does not match the AI-LLM branch of <code>evaluateReleaseGate</code> (<code>packages/quality-metrics/src/gate.ts</code> — 4 AI-LLM axes are appended only when the prefix is <code>@kiwa-test/ai-*</code>). Component test dogfoods stay on the 7-axis common track — Playwright CT is a rendering + interaction surface, not a token-priced generative surface, so cost / latency / token / accuracy do not apply. Mount + interact + a11y round-trip latency still feeds <code>perf.p95Ms</code> so form CT performance stays visible in the report.</p>`,21)])])}const u=t(i,[["render",d]]);export{m as __pageData,u as default};
